const directoryURL=p=>{const u=new URL(p,assetModuleURL);if(!u.pathname.endsWith('/'))u.pathname+='/';return u};
const assetModuleURL=import.meta.url;
import{scope,dataRecord,footData}from'./common.mjs';import{GEOMETRY_PINS}from'../gohyeon-gameplay/geometry-pins.mjs';import{FIXED_REGISTRATION}from'../gohyeon-pair/fixed-registration.mjs';import{GYM4_REVISION,GYM4_GAMEPLAY}from'../gohyeon-gym4/fixed-registration.mjs';import{GYM4_ASSET_MANIFEST_SHA}from'../gohyeon-gym4/asset-pins.mjs';
export const MAPS=Object.freeze({park:'world:area:S4_POW_CAMP_PARK_EDGE',greenbelt:'world:area:S4_GOHYEON_GREENBELT',gym:'world:gym:4'});const base=directoryURL('../'),tokens=new WeakMap,directions=['up','down','left','right'];
function handle(bank,owner=false,signal){let dead=false;bank.refs++;const token=owner?Object.freeze({}):null,live=()=>!dead&&!bank.dead&&!signal?.aborted;const dispose=()=>{if(dead)return;dead=true;signal?.removeEventListener('abort',dispose);if(token)tokens.delete(token);if(--bank.refs===0){bank.dead=true;for(const k of Object.keys(bank.masks))delete bank.masks[k]}};
const safe=(foot,state)=>{try{if(!live()||!Object.hasOwn(bank.pins,state))return false;const[x,y]=footData(foot);return x>=0&&y>=0&&x<bank.width&&y<bank.height&&bank.masks[state][y*bank.width+x]===1}catch{return false}};
const describe=(foot,facing,state)=>{if(!safe(foot,state)||!directions.includes(facing))throw Error('S4_TARGET_UNSAFE');return Object.freeze({mapId:bank.mapId,revision:bank.revision,state,imageSHA:bank.pins[state].imageSHA,maskSHA:bank.pins[state].maskSHA,foot:Object.freeze(footData(foot)),facing})};const validate=p=>{try{const v=dataRecord(p,['mapId','revision','state','imageSHA','maskSHA','foot','facing']),e=describe(v.foot,v.facing,v.state);return ['mapId','revision','state','imageSHA','maskSHA','facing'].every(k=>v[k]===e[k])}catch{return false}};
if(token)tokens.set(token,{bank,live});signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return Object.freeze({safe,describe,validate,get pinsVerified(){return live()},...(owner?{leaseToken:token}:{}),get retainedMaskBytes(){return bank.dead?0:bank.width*bank.height*Object.keys(bank.masks).length},get activeSupportLeases(){return bank.refs},dispose});}
export function borrowSupport(token,mapId){const entry=tokens.get(token);if(!entry?.live()||entry.bank.mapId!==mapId)throw Error('S4_TARGET_SUPPORT_TOKEN');return handle(entry.bank)}
export async function prepareS4TargetSupport(options={}){const{mapId}=options;if(!Object.values(MAPS).includes(mapId))throw Error('S4_TARGET_MAP');const s=scope(options),masks={},pins={};let width=1536,height=1024,revision;try{s.check();if(mapId===MAPS.gym){width=1448;height=1086;revision=GYM4_REVISION;const dir=new URL('gohyeon-gym4/',base),m=JSON.parse(new TextDecoder().decode(await s.pinned(new URL('ASSET_PINS.json',dir),GYM4_ASSET_MANIFEST_SHA)));for(const state of['04','05']){const p=m['safe'+state];masks[state]=await s.pinned(new URL(p.path,dir),p.sha256,p.bytes);pins[state]={imageSHA:GYM4_GAMEPLAY[0].states[state].imageSHA,maskSHA:GYM4_GAMEPLAY[0].states[state].maskSHA};if(p.sha256!==pins[state].maskSHA)throw Error('GYM4_SUPPORT_IDENTITY')}}else{const dir=new URL('gohyeon-gameplay/',base),p=GEOMETRY_PINS.selection;await s.pinned(new URL(p.path,dir),p.sha256,p.bytes);const row=GEOMETRY_PINS.maps.find(m=>m.mapId===mapId),r=FIXED_REGISTRATION.find(r=>r.mapId===mapId);if(!row||!r||r.imageSHA!==row.imageSHA)throw Error('S4_TARGET_IDENTITY');revision=r.revision;const pin=row.selectedSolidSafe;masks.FIXED=await s.pinned(new URL(pin.path,dir),pin.sha256,pin.bytes);pins.FIXED={imageSHA:row.imageSHA,maskSHA:pin.sha256}}for(const b of Object.values(masks))if(b.length!==width*height||b.some(v=>v!==0&&v!==1))throw Error('S4_TARGET_MASK_SHAPE');s.check();const support=handle({mapId,width,height,revision,masks,pins,refs:0,dead:false},true,options.signal);s.dispose();return support}catch(e){s.dispose();throw e}}
